using AtlasPca;
using Xunit;
using static AtlasPca.Corpus.Tests.Conf;

namespace AtlasPca.Corpus.Tests;

// K3 operational-plane artifacts (signed policy bundles, decision log, list-authorized receipts and cursors, grant management) and
// the consistency token, replaying packages/pca/conformance/k3-vectors.json (generated by the TypeScript reference with fixed Ed25519
// seeds). Expected values are exact: codes, reasons and digests.
public class K3VectorTests
{
    // kind -> minimum number of cases (a vector file that loses cases FAILS)
    static readonly Dictionary<string, int> Kinds = new()
    {
        ["fresh_at_verify"] = 5, ["fresh_at_digest"] = 2, ["fresh_at_check"] = 14, ["bundle_digest"] = 2, ["bundle_verify"] = 15, ["log_commit"] = 3,
        ["log_head_verify"] = 4, ["log_inclusion"] = 6, ["log_batch_verify"] = 9, ["list_objects_digest"] = 1, ["list_receipt_verify"] = 6, ["list_bind"] = 2,
        ["list_cursor_verify"] = 11, ["authority_digest"] = 2, ["authority_compare"] = 11, ["amend_verify"] = 16, ["revoke_verify"] = 7, ["need_approve_verify"] = 11,
    };

    static Dictionary<string, object?> Prims()
    {
        var doc = Load("k3-vectors.json");
        Assert.Equal(1L, N(doc["format"]));
        return D(doc["primitives"]);
    }

    static void Each(string kind, Action<Dictionary<string, object?>, Dictionary<string, object?>> f)
    {
        var cases = L(Prims()[kind]);
        Assert.True(cases.Count >= Kinds[kind], $"{kind}: only {cases.Count} cases");
        foreach (var x in cases)
        {
            var c = D(x);
            try { f(D(c["input"]), D(c["expect"])); }
            catch (Xunit.Sdk.XunitException e) { throw new Xunit.Sdk.XunitException($"{kind} / {c["name"]}: {e.Message}"); }
        }
    }

    static List<string> Strings(object? o) => L(o).Cast<string>().ToList();

    [Fact]
    public void EveryKindIsPresent()
    {
        var p = Prims();
        foreach (var k in Kinds.Keys) Assert.True(p.ContainsKey(k), k);
        foreach (var k in p.Keys) Assert.True(Kinds.ContainsKey(k), $"vector kind '{k}' has no replay in this SDK");
    }

    [Fact] public void FreshAtVerify() => Each("fresh_at_verify", (i, e) => Assert.Equal((bool)e["valid"]!, FreshAt.Verify(i["token"], (string)i["signer"]!)));

    [Fact] public void FreshAtDigest() => Each("fresh_at_digest", (i, e) => Assert.Equal((string)e["digest"]!, FreshAt.Digest(i["token"])));

    [Fact]
    public void FreshAtCheck() => Each("fresh_at_check", (i, e) =>
    {
        var o = D(i["options"]);
        var local = FreshAtState.FromJson(i["local"]);
        Assert.NotNull(local);
        long? maxAge = o.TryGetValue("maxTokenAgeMs", out var m) ? N(m) : null;
        var v = FreshAt.Check(i["token"], local!, (string)o["signer"]!, (string)o["scope"]!, N(o["now"]), maxAge);
        Assert.Equal((string)e["decision"]!, v.Decision);
        Assert.Equal(e.GetValueOrDefault("code") as string, v.Code);
        var behind = e.ContainsKey("behind") ? Strings(e["behind"]) : new List<string>();
        Assert.True(behind.SequenceEqual(v.Behind), $"behind [{string.Join(",", v.Behind)}], want [{string.Join(",", behind)}]");
    });

    [Fact] public void BundleDigest() => Each("bundle_digest", (i, e) => Assert.Equal((string)e["digest"]!, K3.BundleDigest(i["bundle"])));

    [Fact]
    public void BundleVerify() => Each("bundle_verify", (i, e) =>
    {
        var o = D(i["options"]);
        (long Revision, string Digest)? last = null;
        if (o.GetValueOrDefault("last") is Dictionary<string, object?> lg) last = (N(lg["revision"]), (string)lg["digest"]!);
        var v = K3.VerifyBundle(i["bundle"], Strings(o["signers"]), N(o["threshold"]), (string)o["verifierVersion"]!, last);
        Assert.Equal((bool)e["ok"]!, v.Ok);
        if (v.Ok)
        {
            Assert.Equal(N(e["revision"]), v.Revision);
            Assert.Equal((string)e["digest"]!, v.Digest);
            Assert.True(Strings(e["signers"]).SequenceEqual(v.Signers), $"signers [{string.Join(",", v.Signers)}]");
        }
        else
        {
            Assert.Equal((string)e["code"]!, v.Code);
            Assert.Equal((string)e["reason"]!, v.Reason);
        }
    });

    [Fact] public void LogCommit() => Each("log_commit", (i, e) => Assert.Equal((string)e["commit"]!, K3.RecordCommit(i["record"])));

    [Fact] public void LogHeadVerify() => Each("log_head_verify", (i, e) => Assert.Equal((bool)e["valid"]!, K3.VerifyLogHead(i["head"], (string)i["signer"]!)));

    [Fact]
    public void LogInclusion() => Each("log_inclusion", (i, e) =>
        Assert.Equal((bool)e["valid"]!, K3.VerifyRecordInclusion(i["record"], i["proof"], i["head"], (string)i["signer"]!)));

    [Fact]
    public void LogBatchVerify() => Each("log_batch_verify", (i, e) =>
    {
        var st = D(i["state"]);
        var v = K3.VerifyBatch(i["batch"], N(st["next"]), (string)st["lastCommit"]!, (string)i["signer"]!);
        Assert.Equal((bool)e["ok"]!, v.Ok);
        if (v.Ok)
        {
            Assert.Equal(N(e["next"]), v.Next);
            Assert.Equal((string)e["lastCommit"]!, v.LastCommit);
        }
        else Assert.Equal((string)e["reason"]!, v.Reason);
    });

    [Fact] public void ListObjectsDigest() => Each("list_objects_digest", (i, e) => Assert.Equal((string)e["digest"]!, K3.ObjectsDigest(Strings(i["objects"]))));

    [Fact]
    public void ListReceiptVerify() => Each("list_receipt_verify", (i, e) =>
        Assert.Equal((bool)e["valid"]!, K3.VerifyListReceipt(i["receipt"], (string)i["signer"]!, i.ContainsKey("objects") ? Strings(i["objects"]) : null)));

    [Fact] public void ListBind() => Each("list_bind", (i, e) => Assert.Equal((string)e["digest"]!, K3.ListBind(i["bind"])));

    [Fact]
    public void ListCursorVerify() => Each("list_cursor_verify", (i, e) =>
    {
        var v = K3.VerifyListCursor(i["cursor"], (string)i["signer"]!, i.GetValueOrDefault("bind"));
        Assert.Equal((bool)e["ok"]!, v.Ok);
        if (v.Ok)
        {
            Assert.Equal(e.GetValueOrDefault("inner") as string, v.Inner);
            Assert.Equal(N(e["skip"]), v.Skip);
        }
        else Assert.Equal((string)e["reason"]!, v.Reason);
    });

    [Fact] public void AuthorityDigest() => Each("authority_digest", (i, e) => Assert.Equal((string)e["digest"]!, K3.AuthorityDigest(i["authority"])));

    [Fact] public void AuthorityCompare() => Each("authority_compare", (i, e) => Assert.Equal((string)e["order"]!, K3.CompareAuthority(D(i["old"]), D(i["new"]))));

    [Fact]
    public void AmendVerify() => Each("amend_verify", (i, e) =>
    {
        var v = K3.VerifyAmendment(D(i["grant"]), i["request"], (bool)i["step_up_ok"]!);
        Assert.Equal((bool)e["ok"]!, v.Ok);
        if (v.Ok)
        {
            Assert.Equal((bool)e["widens"]!, v.Widens);
            Assert.Equal((string)e["next_digest"]!, K3.AuthorityDigest(v.Authority));
        }
        else Assert.Equal((string)e["code"]!, v.Code);
    });

    [Fact]
    public void RevokeVerify() => Each("revoke_verify", (i, e) =>
    {
        var v = K3.VerifyRevokeSignature(D(i["root"]), i["scope"], i.GetValueOrDefault("sig"));
        Assert.Equal((bool)e["ok"]!, v.Ok);
        if (v.Ok) Assert.Equal((string)e["scope"]!, v.Scope);
        else Assert.Equal((string)e["code"]!, v.Code);
    });

    [Fact]
    public void NeedApproveVerify() => Each("need_approve_verify", (i, e) =>
    {
        var v = K3.VerifyNeedApproval(D(i["need_request"]), D(i["grant"]), i["approved"], i.GetValueOrDefault("sig"), (bool)i["step_up_ok"]!);
        Assert.Equal((bool)e["ok"]!, v.Ok);
        if (v.Ok) Assert.Equal((string)e["authority_digest"]!, K3.AuthorityDigest(v.Authority));
        else Assert.Equal((string)e["code"]!, v.Code);
    });

    [Fact]
    public void EveryVerifierIsTotalOnGarbage()
    {
        object?[] junk = { null, "x", true, new List<object?>(), new Dictionary<string, object?>(), new Num("7") };
        foreach (var j in junk)
        {
            Assert.False(FreshAt.Verify(j, "s"));
            Assert.Equal("bad_token", FreshAt.Check(j, new FreshAtState(0, 0, 0, 0, "d"), "s", "scope", 0).Code);
            Assert.False(K3.VerifyBundle(j, new[] { "s" }, 1, "0.5.0").Ok);
            Assert.False(K3.VerifyLogHead(j, "s"));
            Assert.False(K3.VerifyRecordInclusion(j, j, j, "s"));
            Assert.False(K3.VerifyBatch(j, 0, "", "s").Ok);
            Assert.False(K3.VerifyListReceipt(j, "s"));
            Assert.False(K3.VerifyListCursor(j, "s").Ok);
            Assert.False(K3.VerifyAmendment(new Dictionary<string, object?>(), j, true).Ok);
            Assert.False(K3.VerifyRevokeSignature(new Dictionary<string, object?>(), j, j).Ok);
            Assert.False(K3.VerifyNeedApproval(new Dictionary<string, object?>(), new Dictionary<string, object?>(), j, j, true).Ok);
            Assert.Equal("incomparable", K3.CompareAuthority(new Dictionary<string, object?>(), new Dictionary<string, object?>()));
        }
    }
}
